#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const root=path.resolve(process.argv[2]||process.cwd());
const marker=path.join(root,'src','App.tsx');
if(!fs.existsSync(marker)){
  console.error('Nenašiel som src/App.tsx. Spustite inštalátor v koreňovom adresári projektu alebo zadajte cestu ako argument.');
  process.exit(1);
}

const files={"src/App.tsx": "", "src/views/DepartmentPortal.tsx": "", "src/views/ItCosts.tsx": "", "src/views/ItCosts.css": "", "src/data/itCosts.json": "", "scripts/extract_it_costs.py": "", "README.md": "", "RELEASE_NOTES.md": "", "RELEASE_NOTES_0.21.md": "", "README_NASADENIE_0.21.txt": "", "IT_COST_CLASSIFICATION.md": ""};
for(const [relative,encoded] of Object.entries(files)){
  const target=path.join(root,relative);
  fs.mkdirSync(path.dirname(target),{recursive:true});
  fs.writeFileSync(target,Buffer.from(encoded,'base64'));
  console.log('zapísané',relative);
}

function replaceRequired(relative,pattern,replacement){
  const target=path.join(root,relative);
  let text=fs.readFileSync(target,'utf8');
  if(!pattern.test(text)){console.error('Neočakávaný obsah '+relative+' – verzia nebola zmenená.');process.exit(1);}
  text=text.replace(pattern,replacement);
  fs.writeFileSync(target,text);
  console.log('aktualizované',relative);
}

replaceRequired('package.json',/"version"\s*:\s*"0\.20\.0"/,'"version": "0.21.0"');
replaceRequired('src/lib/storage.ts',/const CURRENT_VERSION = '0\.20\.0'/,"const CURRENT_VERSION = '0.21.0'");
replaceRequired('src/data/seed.json',/"version"\s*:\s*"0\.20\.0"/,'"version": "0.21.0"');

console.log('\nIS Riadenie odboru bolo aktualizované na v0.21.0 – IT náklady a finančná inteligencia.');
console.log('Databázová migrácia nie je potrebná. Spustite npm run check a npm run build.');
